mapper.insert:
INSERT INTO TB_INVOICE_MASTER (
      COMPANY_CODE
    , INVOICE_NO
    , CUST_CODE
    , INVOICE_TYPE
    , STATUS
    , ISSUE_DATE
    , DOCUMENT_DATE
    , TOTAL_SUPPLY_PRICE
    , TOTAL_TAX_PRICE
    , TOTAL_AMOUNT
)
VALUES (
      #{companyCode}
    , #{invoiceNo}
    , #{custCode}
    , #{invoiceType}
    , #{status}
    , #{issueDate}
    , #{documentDate}
    , #{totalSupplyPrice}
    , #{totalTaxPrice}
    , #{totalAmount}
)

INSERT INTO TB_INVOICE_DETAIL (
      INVOICE_DETAIL_NO
    , COMPANY_CODE
    , INVOICE_NO
    , SKU
    , QTY
    , UNIT_PRICE
    , SUPPLY_PRICE
    , TAX_PRICE
)
VALUES (
      #{invoiceDetailNo}
    , #{companyCode}
    , #{invoiceNo}
    , #{sku}
    , #{qty}
    , #{unitPrice}
    , #{supplyPrice}
    , #{taxPrice}
)

mapper.select:
SELECT inv.company_code , inv.invoice_no , inv.issue_date , inv.document_date , inv.cust_code , cst.cust_name , inv.total_supply_price , inv.total_tax_price , inv.total_amount FROM tb_invoice_master inv JOIN tb_cust_master cst ON inv.company_code = cst.company_code AND inv.cust_code = cst.cust_code WHERE inv.company_code = #{companyCode} AND inv.issue_date BETWEEN #{fromDate} AND #{toDate}
AND inv.cust_code = #{custCode}
ORDER BY inv.issue_date ASC , inv.invoice_no ASC
